const OS_STATUS_NAMES=Object.freeze({
  0:'Pendente',1:'Cancelada',2:'Finalizada',3:'Produtos Faturados',
  4:'Docs a Receber Gerados',5:'Serviços Faturados',
  6:'Produtos e Serviços Faturados'
});
function osStatusLabel(value){
  if(value==null||String(value).trim()==='')return 'Não informado';
  const code=String(value).trim();
  return Object.prototype.hasOwnProperty.call(OS_STATUS_NAMES,code)
    ? OS_STATUS_NAMES[code]+' (código '+code+')'
    : 'Código '+code;
}

