def _anexar_nomes_produtos(con, itens):
    """Adiciona nomes do cadastro sem remover o ID/codigo de barras originais.

    Uma consulta de metadados e leitura em lotes de IDs; nao faz N+1.
    Quando nao existe nome disponivel, o front-end exibe Produto #ID.
    """
    if not itens:
        return
    coluna = _display_column(con, 'produto')
    if not coluna:
        return
    codigos = list(dict.fromkeys(
        item.get('produto') for item in itens if item.get('produto') is not None
    ))
    nomes = {}
    for inicio in range(0, len(codigos), 250):
        lote = codigos[inicio:inicio + 250]
        marcadores = ','.join('?' for _ in lote)
        try:
            produtos = run(con, f"""SELECT id_produto AS codigo,
                CAST({_optical_sql_name(coluna)} AS NVARCHAR(1000))
                  AS nome_produto
                FROM dbo.produto WHERE id_produto IN ({marcadores})""", lote)
        except DatabaseError:
            # Ausencia de cadastro/permissao nao impede abrir a OS.
            return
        for produto in produtos:
            nome = produto.get('nome_produto')
            if nome is not None and str(nome).strip():
                nomes[produto['codigo']] = str(nome).strip()
    for item in itens:
        nome = nomes.get(item.get('produto'))
        if nome:
            item['nome_produto'] = nome


