    return _cpf_search_extra(con, filters['q'])
return _product_extra(con) if include_products else []

key = _cpf_cache_key(digits, cache_scope)
cached = None
if key is not None:
    with _CPF_CACHE_LOCK:
        entry = _CPF_ID_CACHE.get(key)
        if entry and entry[0] > time.monotonic():
            cached = entry[1]
if cached is None:
    ids = _cpf_lookup_ids(con, digits)
    if key is not None:
        with _CPF_CACHE_LOCK:
            if len(_CPF_ID_CACHE) >= 64:
                # Cache curto e limitado, evita acumulo de historico.
                _CPF_ID_CACHE.clear()
            _CPF_ID_CACHE[key] = (time.monotonic() + _CPF_CACHE_TTL, ids)
else:
    ids = cached
if not ids:
    return [('1=0', [])]
params = ','.join('?' for _ in ids)
return [('o.id_entidade_cliente IN (' + params + ')', list(ids))]

